import attr
import pickle

@attr.s(slots=True)
class A:
    x: int = attr.ib()
    y: int = attr.ib()

a2 = A(x=0, y=0)
print("Testing with tuple...")
try:
    a2.__setstate__((1, 2))
    print(f"Success: {a2}")
except Exception as e:
    print(f"Failure: {e}")

a3 = A(x=0, y=0)
print("Testing with dict...")
try:
    a3.__setstate__({'x': 1, 'y': 2})
    print(f"Success: {a3}")
except Exception as e:
    print(f"Failure: {e}")

